package org.astross.studio;

import org.json.JSONArray;
import org.json.JSONObject;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Iterator;
import java.util.regex.Pattern;

/** Small fail-closed evaluator for the checked-in Draft-07 Content input schema. */
final class GithubContentValidator {
    private static final String[] ALLOWED={"$schema","title","description","default","type","properties","required","additionalProperties","items","maxItems","maxLength","minLength","maximum","minimum","const","enum","pattern","format","anyOf","oneOf","allOf","propertyNames"};
    private static final String[] IMPLEMENTED_INVARIANTS={"total-record-limit","unique-record-ids","unique-public-routes","unique-field-ids","unique-category-ids-and-slugs","excerpt-source-is-text","collection-layout-kind","item-collection-reference","content-item-title","published-gallery-image","automatic-description-source","item-value-field-reference","item-value-field-type","collection-view-reference","collection-view-category-filter","link-scheme-safety","rich-text-block-kind","rich-text-limits"};
    private final JSONObject schema;
    private final String schemaError;
    private final String invariantError;
    GithubContentValidator(JSONObject schema){this(schema,null);}
    private GithubContentValidator(JSONObject schema,String invariantError){this.schema=schema;this.schemaError=vocabularyError(schema,"$");this.invariantError=invariantError;}
    static GithubContentValidator from(InputStream input)throws Exception{
        if(input==null)throw new IllegalStateException("Canonical content schema asset is missing.");
        java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();byte[] buffer=new byte[4096];int count;
        while((count=input.read(buffer))!=-1){if(bytes.size()+count>100_000)throw new IllegalStateException("Canonical content schema asset is too large.");bytes.write(buffer,0,count);}
        return new GithubContentValidator(new JSONObject(new String(bytes.toByteArray(),StandardCharsets.UTF_8)));
    }
    static GithubContentValidator from(InputStream schema,InputStream manifest)throws Exception{
        GithubContentValidator base=from(schema);if(manifest==null)throw new IllegalStateException("Canonical content invariant manifest is missing.");
        java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();byte[] buffer=new byte[2048];int count;while((count=manifest.read(buffer))!=-1){if(bytes.size()+count>50_000)throw new IllegalStateException("Canonical invariant manifest is too large.");bytes.write(buffer,0,count);}
        JSONObject json=new JSONObject(new String(bytes.toByteArray(),StandardCharsets.UTF_8));if(json.optInt("contentSchemaVersion",-1)!=2)throw new IllegalStateException("Canonical content invariant manifest has an unsupported version.");
        JSONArray ids=json.getJSONArray("invariants");java.util.HashSet<String> actual=new java.util.HashSet<>();for(int i=0;i<ids.length();i++)actual.add(ids.getJSONObject(i).getString("id"));java.util.HashSet<String> expected=new java.util.HashSet<>(java.util.Arrays.asList(IMPLEMENTED_INVARIANTS));
        if(actual.size()!=ids.length()||!actual.equals(expected))throw new IllegalStateException("Canonical content invariants changed without a matching native validator.");
        return new GithubContentValidator(base.schema,null);
    }
    void validate(JSONObject value)throws Exception{
        if(schemaError!=null)throw new IllegalArgumentException(schemaError);if(invariantError!=null)throw new IllegalArgumentException(invariantError);
        if(value==null||value.toString().getBytes(StandardCharsets.UTF_8).length>GithubProjectClient.MAX_CONTENT_BYTES)throw new IllegalArgumentException("Project content is too large.");
        check(value,schema,"$");
        invariants(value);
    }
    private static String vocabularyError(JSONObject rule,String path){
        Iterator<String> names=rule.keys();while(names.hasNext()){String name=names.next();if(!allowed(name))return "Unsupported canonical schema assertion: "+name;Object child=rule.opt(name);
            if("properties".equals(name)&&child instanceof JSONObject){JSONObject properties=(JSONObject)child;Iterator<String> it=properties.keys();while(it.hasNext()){String property=it.next();Object sub=properties.opt(property);if(sub instanceof JSONObject){String error=vocabularyError((JSONObject)sub,path+"."+property);if(error!=null)return error;}}}
            else if(("items".equals(name)||"additionalProperties".equals(name)||"propertyNames".equals(name))&&child instanceof JSONObject){String error=vocabularyError((JSONObject)child,path+"."+name);if(error!=null)return error;}
            else if(("allOf".equals(name)||"anyOf".equals(name)||"oneOf".equals(name))&&child instanceof JSONArray){JSONArray branches=(JSONArray)child;for(int i=0;i<branches.length();i++){Object branch=branches.opt(i);if(branch instanceof JSONObject){String error=vocabularyError((JSONObject)branch,path+"."+name+"["+i+"]");if(error!=null)return error;}}}
        }return null;
    }
    private void check(Object value,JSONObject rule,String path)throws Exception{
        Iterator<String> keys=rule.keys();while(keys.hasNext()){String key=keys.next();if(!allowed(key))throw new IllegalArgumentException("Unsupported canonical schema assertion: "+key);}
        if(rule.has("type")&&!matchesType(value,rule.optString("type")))fail(path,"type");
        if(rule.has("const")&&!equal(value,rule.get("const")))fail(path,"const");
        if(rule.has("enum")){boolean found=false;JSONArray values=rule.getJSONArray("enum");for(int i=0;i<values.length();i++)if(equal(value,values.get(i)))found=true;if(!found)fail(path,"enum");}
        if(value instanceof String){String s=(String)value;if(rule.has("minLength")&&s.length()<rule.getInt("minLength"))fail(path,"minLength");if(rule.has("maxLength")&&s.length()>rule.getInt("maxLength"))fail(path,"maxLength");if(rule.has("pattern")&&!Pattern.compile(rule.getString("pattern")).matcher(s).find())fail(path,"pattern");if(rule.has("format")&&!validFormat(s,rule.getString("format")))fail(path,"format");}
        if(value instanceof Number){double n=((Number)value).doubleValue();if(rule.has("minimum")&&n<rule.getDouble("minimum"))fail(path,"minimum");if(rule.has("maximum")&&n>rule.getDouble("maximum"))fail(path,"maximum");if("integer".equals(rule.optString("type"))&&n!=Math.rint(n))fail(path,"integer");}
        if(value instanceof JSONArray){JSONArray a=(JSONArray)value;if(rule.has("maxItems")&&a.length()>rule.getInt("maxItems"))fail(path,"maxItems");if(rule.has("items"))for(int i=0;i<a.length();i++)check(a.get(i),rule.getJSONObject("items"),path+"["+i+"]");}
        if(value instanceof JSONObject){JSONObject o=(JSONObject)value;JSONObject props=rule.optJSONObject("properties");JSONArray required=rule.optJSONArray("required");if(required!=null)for(int i=0;i<required.length();i++)if(!o.has(required.getString(i)))fail(path,"required "+required.getString(i));
            if(rule.has("propertyNames")){JSONObject pn=rule.getJSONObject("propertyNames");for(String name:keys(o))check(name,pn,path+".<key>");}
            for(String name:keys(o)){JSONObject child=props==null?null:props.optJSONObject(name);if(child!=null)check(o.get(name),child,path+"."+name);else if(props!=null&&!rule.has("additionalProperties")&&!rule.has("propertyNames"))fail(path+"."+name,"unknown property");else if(rule.has("additionalProperties")){Object extra=rule.get("additionalProperties");if(Boolean.FALSE.equals(extra))fail(path+"."+name,"additionalProperties");if(extra instanceof JSONObject){JSONObject extraRule=(JSONObject)extra;if(extraRule.length()==0&&props!=null&&!rule.has("propertyNames"))fail(path+"."+name,"unknown property");check(o.get(name),extraRule,path+"."+name);}}}
        }
        for(String comb:new String[]{"allOf","anyOf","oneOf"})if(rule.has(comb)){JSONArray branches=rule.getJSONArray(comb);int valid=0;for(int i=0;i<branches.length();i++){try{check(value,branches.getJSONObject(i),path);valid++;}catch(Exception ignored){}}if(("allOf".equals(comb)&&valid!=branches.length())||("anyOf".equals(comb)&&valid==0)||("oneOf".equals(comb)&&valid!=1))fail(path,comb);}
    }
    private void invariants(JSONObject root)throws Exception{
        // These cross-record rules are Zod superRefine checks, outside JSON Schema.
        java.util.HashSet<String> ids=new java.util.HashSet<>(),routes=new java.util.HashSet<>();java.util.HashMap<String,JSONObject> collections=new java.util.HashMap<>();
        JSONArray pages=root.getJSONArray("pages"),cols=root.getJSONArray("collections"),items=root.getJSONArray("items");
        for(int i=0;i<pages.length();i++){JSONObject p=pages.getJSONObject(i);unique(ids,p.getString("id"),"record id");String slug=p.getString("slug");if(!safeRootSlug(slug))fail("$.pages["+i+"].slug","reserved route");unique(routes,slug,"route");}
        for(int i=0;i<cols.length();i++){JSONObject c=cols.getJSONObject(i);unique(ids,c.getString("id"),"record id");String slug=c.getString("slug");if(!safeRootSlug(slug)||!safeRootSlug(c.getString("routeBase")))fail("$.collections["+i+"]","reserved route");unique(routes,slug,"route");collections.put(c.getString("id"),c);if(("content".equals(c.optString("kind"))&&"masonry".equals(c.optString("listLayout")))||("gallery".equals(c.optString("kind"))&&"list".equals(c.optString("listLayout"))))fail("$.collections["+i+"]","unsupported collection layout");java.util.HashSet<String> fields=new java.util.HashSet<>();JSONArray fs=c.getJSONArray("fields");for(int j=0;j<fs.length();j++){JSONObject f=fs.getJSONObject(j);unique(fields,f.getString("id"),"field id");if("category".equals(f.optString("type"))){java.util.HashSet<String> catIds=new java.util.HashSet<>(),slugs=new java.util.HashSet<>();JSONArray cats=f.getJSONArray("categories");for(int k=0;k<cats.length();k++){JSONObject cat=cats.getJSONObject(k);unique(catIds,cat.getString("id"),"category id");unique(slugs,cat.getString("slug"),"category slug");}}}}
        if(pages.length()+items.length()>500)fail("$","total record limit");
        for(String collectionId:collections.keySet()){JSONObject col=collections.get(collectionId);String excerpt=col.optString("excerptSourceFieldId","");if(!excerpt.isEmpty()&&!isFieldType(col,excerpt,"text"))fail("$.collections","excerpt text field reference");}
        for(int i=0;i<items.length();i++){JSONObject item=items.getJSONObject(i);unique(ids,item.getString("id"),"record id");JSONObject col=collections.get(item.getString("collectionId"));if(col==null)fail("$.items["+i+"]","collection reference");unique(routes,col.getString("routeBase")+"/"+item.getString("slug"),"route");JSONArray fs=col.getJSONArray("fields");java.util.HashMap<String,JSONObject> fields=new java.util.HashMap<>();for(int j=0;j<fs.length();j++){JSONObject f=fs.getJSONObject(j);fields.put(f.getString("id"),f);}JSONObject values=item.getJSONObject("values");for(String key:keys(values)){JSONObject f=fields.get(key);if(f==null)fail("$.items["+i+"].values","field reference");validateFieldValue(values.get(key),f);}
            if("auto".equals(item.optJSONObject("description").optString("source"))&&!isFieldType(col,col.optString("excerptSourceFieldId",""),"text"))fail("$.items["+i+"]","automatic description excerpt field");
            if(item.optBoolean("published",false)&&"gallery".equals(col.optString("kind"))&&!hasGalleryImage(values,col))fail("$.items["+i+"]","published gallery image");
        }
        for(int i=0;i<pages.length();i++){JSONArray blocks=pages.getJSONObject(i).getJSONArray("blocks");for(int j=0;j<blocks.length();j++){JSONObject b=blocks.getJSONObject(j);if("richText".equals(b.optString("type")))validateRichTextInvariants(b.getJSONObject("document"));if(!"collectionView".equals(b.optString("type")))continue;JSONObject c=collections.get(b.optString("collectionId"));if(c==null)fail("$.pages.blocks","collection view reference");String cf=b.optString("categoryFieldId");if(!cf.isEmpty()){JSONObject field=null;JSONArray fs=c.getJSONArray("fields");for(int k=0;k<fs.length();k++)if(cf.equals(fs.getJSONObject(k).optString("id")))field=fs.getJSONObject(k);if(field==null||!"category".equals(field.optString("type")))fail("$.pages.blocks","category field reference");java.util.HashSet<String> cat=new java.util.HashSet<>();JSONArray cats=field.getJSONArray("categories");for(int k=0;k<cats.length();k++)cat.add(cats.getJSONObject(k).getString("id"));JSONArray refs=b.optJSONArray("categoryIds");if(refs!=null)for(int k=0;k<refs.length();k++)if(!cat.contains(refs.getString(k)))fail("$.pages.blocks","category id reference");}}}
    }
    private JSONObject richTextDocumentRule()throws Exception{return schema.getJSONObject("properties").getJSONObject("pages").getJSONObject("items").getJSONObject("properties").getJSONObject("blocks").getJSONObject("items").getJSONArray("oneOf").getJSONObject(0).getJSONObject("properties").getJSONObject("document");}
    private static void validateRichTextInvariants(JSONObject document)throws Exception{long text=0,images=0;JSONArray blocks=document.getJSONArray("blocks");for(int i=0;i<blocks.length();i++){JSONObject block=blocks.getJSONObject(i);String type=block.optString("type");if("heading".equals(type)&&!block.has("level"))fail("rich text","heading level");if("paragraph".equals(type)&&block.has("level"))fail("rich text","paragraph level");if("gallery".equals(type)){images+=block.getJSONArray("images").length();continue;}JSONArray children=block.getJSONArray("children");for(int j=0;j<children.length();j++){JSONObject node=children.getJSONObject(j);if("image".equals(node.optString("type"))){images++;continue;}text+=node.optString("text","").length();JSONArray marks=node.optJSONArray("marks");if(marks!=null){java.util.HashSet<String> seen=new java.util.HashSet<>();for(int k=0;k<marks.length();k++)unique(seen,marks.getString(k),"rich text mark");}}}if(text>1_500_000||images>33_000)fail("rich text","limits");}
    private static boolean safeRootSlug(String value){return value.matches("[a-z0-9]+(?:-[a-z0-9]+)*")&&!value.matches("api|admin|media");}
    private static boolean isFieldType(JSONObject col,String id,String type)throws Exception{JSONArray fields=col.getJSONArray("fields");for(int i=0;i<fields.length();i++){JSONObject f=fields.getJSONObject(i);if(id.equals(f.optString("id")))return type.equals(f.optString("type"));}return false;}
    private static boolean hasGalleryImage(JSONObject values,JSONObject col)throws Exception{JSONArray fields=col.getJSONArray("fields");for(int i=0;i<fields.length();i++){JSONObject f=fields.getJSONObject(i);if("gallery".equals(f.optString("type"))&&values.has(f.getString("id"))&&values.getJSONArray(f.getString("id")).length()>0)return true;}return false;}
    private static boolean safeHref(String href){if(href.isEmpty()||href.length()>2000||!href.equals(href.trim()))return false;if(href.startsWith("/"))return !href.startsWith("//")&&!href.contains("\\");try{java.net.URI uri=new java.net.URI(href);String scheme=uri.getScheme();if(scheme==null)return false;scheme=scheme.toLowerCase(java.util.Locale.ROOT);if("http".equals(scheme)||"https".equals(scheme))return uri.getHost()!=null;return "mailto".equals(scheme)||"tel".equals(scheme);}catch(Exception e){return false;}}
    private void validateFieldValue(Object value,JSONObject field)throws Exception{String type=field.optString("type");if("text".equals(type)){if("rich".equals(field.optString("format"))){if(!(value instanceof JSONObject))fail("item value","rich text field");check(value,richTextDocumentRule(),"item rich text");validateRichTextInvariants((JSONObject)value);}else if(!(value instanceof String)||((String)value).length()>50_000)fail("item value","text field maxLength");}if("link".equals(type)){if(!(value instanceof JSONObject))fail("item value","link field");JSONObject link=(JSONObject)value;Object href=link.opt("href"),label=link.opt("label");if(!(href instanceof String)||!safeHref((String)href)||!(label instanceof String)||((String)label).length()>200)fail("item value","unsafe link");}if("gallery".equals(type)){if(!(value instanceof JSONArray))fail("item value","gallery field");JSONArray images=(JSONArray)value;if(field.has("maxItems")&&images.length()>field.getInt("maxItems"))fail("item value","gallery maxItems");JSONObject mediaRule=schema.getJSONObject("properties").getJSONObject("items").getJSONObject("items").getJSONObject("properties").getJSONObject("coverImage");for(int i=0;i<images.length();i++)check(images.get(i),mediaRule,"gallery media");}if("category".equals(type)){if(!(value instanceof JSONArray)||((JSONArray)value).length()>500)fail("item value","category field");java.util.HashSet<String> allowed=new java.util.HashSet<>();JSONArray cats=field.getJSONArray("categories");for(int i=0;i<cats.length();i++)allowed.add(cats.getJSONObject(i).getString("id"));JSONArray selected=(JSONArray)value;for(int i=0;i<selected.length();i++)if(!allowed.contains(selected.getString(i)))fail("item value","category id");}}
    private static java.util.Set<String> keys(JSONObject object){java.util.HashSet<String> result=new java.util.HashSet<>();Iterator<String> it=object.keys();while(it.hasNext())result.add(it.next());return result;}
    private static void unique(java.util.Set<String> set,String value,String what){if(!set.add(value))throw new IllegalArgumentException("Duplicate "+what+" in project content.");}
    private static boolean allowed(String k){for(String a:ALLOWED)if(a.equals(k))return true;return false;}
    private static boolean matchesType(Object v,String t){if("object".equals(t))return v instanceof JSONObject;if("array".equals(t))return v instanceof JSONArray;if("string".equals(t))return v instanceof String;if("boolean".equals(t))return v instanceof Boolean;if("number".equals(t))return v instanceof Number;if("integer".equals(t))return v instanceof Number&&((Number)v).doubleValue()==Math.rint(((Number)v).doubleValue());return false;}
    private static boolean validFormat(String s,String f){if("uuid".equals(f))return s.matches("(?i)([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)");if("email".equals(f))return s.matches("[^@\\s]+@[^@\\s]+\\.[^@\\s]+")&&!s.contains("..");return false;}
    private static boolean equal(Object a,Object b){return a==null?b==null:a.toString().equals(b.toString());}
    private static void fail(String path,String rule){throw new IllegalArgumentException("Project content failed canonical validation at "+path+" ("+rule+").");}
}
